{
  "muc_phan_loai": "KHÁM SỚM",
  "mo_ta_benh_nhan": "Bệnh nhân 65 tuổi",
  "trich_dan_tu_nguoi_benh": [
    "65",
    "female",
    "moderate"
  ],
  "cac_menh_de": [
    {
      "menh_de": "Đau bụng cấp ở bệnh nhân cao tuổi cần được đánh giá lâm sàng để loại trừ các tình trạng bệnh lý nghiêm trọng.",
      "ket_qua_doi_chieu": "supports",
      "marker": "[1]",
      "ly_do": "Các đoạn trích khẳng định đau bụng cấp ở người cao tuổi thường có các bệnh lý nghiêm trọng (như thiếu máu cục bộ mạc treo) và nhấn mạnh tầm quan trọng của việc đánh giá lâm sàng, chẩn đoán hình ảnh (CT) để thay đổi kế hoạch điều trị, cũng như việc cần thiết phải thực hiện thăm khám kỹ lưỡng để nhận diện các bệnh lý tiềm ẩn."
    },
    {
      "menh_de": "Việc vắng mặt các triệu chứng toàn thân như sốt, khó thở và nôn trong đau bụng cấp có thể gợi ý khả năng thấp về các tình trạng cấp cứu đe dọa tính mạng ngay lập tức.",
      "ket_qua_doi_chieu": "unsupported",
      "marker": "",
      "ly_do": "Các đoạn trích liệt kê sốt, nôn, khó thở như là các triệu chứng đi kèm hoặc dấu hiệu cảnh báo cần chú ý trong đau bụng cấp, nhưng không có đoạn nào khẳng định rằng sự vắng mặt của các triệu chứng này giúp loại trừ hoặc làm giảm khả năng xảy ra các tình trạng đe dọa tính mạng."
    },
    {
      "menh_de": "Trạng thái tinh thần ổn định và khả năng duy trì hoạt động bình thường ở bệnh nhân cao tuổi bị đau bụng hỗ trợ cho chiến lược theo dõi sát.",
      "ket_qua_doi_chieu": "unsupported",
      "marker": "",
      "ly_do": "Các đoạn trích tập trung vào việc nhận diện các dấu hiệu nguy hiểm (như viêm phúc mạc, thiếu máu cục bộ) và khuyến cáo đánh giá khẩn cấp đối với bệnh nhân có dấu hiệu bất ổn, nhưng không có đoạn nào khẳng định rằng trạng thái tinh thần ổn định và khả năng chức năng được bảo tồn là đủ cơ sở để chọn chiến lược theo dõi sát thay vì can thiệp chẩn đoán sâu hơn."
    }
  ]
}

{
  "menh_de": "Stable mental status and preserved functional capacity in elderly patients with abdominal pain support a strategy of close observation.",
  "lap_luan_goc": "Mức tỉnh táo bình thường, hoạt động và ăn uống bình thường. Có người theo dõi 24h.",
  "cac_doan_trich": [
    {
      "chunk_id": "doc-e643c7bd5f09-chunk-46",
      "publisher": "aafp.org",
      "noi_dung": "2\n,\n69\nPatients older than 65 years with peritonitis are one-half as likely to manifest the characteristic signs of rebound tenderness or guarding.\n69\nCT may be more useful in older patients with acute abdominal pain because one large retrospective analysis showed that imaging changes treatment plans more than 65% of the time.\n70\nAcute mesenteric ischemia, which commonly presents with severe pain and an unrevealing examination, is also more common in older patients. The higher rates of atherosclerosis and atrial fibrillation in older patients are risk factors because approximately 50% of acute mesenteric ischemia events are caused by emboli."
    },
    {
      "chunk_id": "doc-e643c7bd5f09-chunk-18",
      "publisher": "aafp.org",
      "noi_dung": "can provide clues to help identify the cause (e.g., nonsteroidal analgesic use should increase suspicion for gastritis or peptic ulcer disease). Previous abdominal surgery, radiation, Crohn disease, or malignancy should prompt consideration of small bowel obstruction.\n22\n,\n23\nPHYSICAL EXAMINATION\nExamination of the patient with acute abdominal pain should start by rapidly assessing clinical status. Abnormal vital signs such as fever, tachycardia, and hypotension help identify patients at the highest risk. During the history and physical examination, stillness can suggest peritonitis, or writhing can suggest biliary or renal colic.\n20\nThe abdominal examination begins with an inspection followed by auscultation, percussion, and palpation."
    },
    {
      "chunk_id": "doc-0de8f1773501-chunk-67",
      "publisher": "ncbi.nlm.nih.gov",
      "noi_dung": "Patients can lower their risk of acute abdomen by adopting a healthy lifestyle, consuming a well-balanced diet, and limiting alcohol and tobacco use. Additionally, regularly monitoring chronic conditions such as gallstones and inflammatory bowel disease, along with following recommended screening guidelines for colon cancer and abdominal aortic aneurysms, can help prevent its occurrence. Clinicians should educate patients taking high-risk medications, such as nonsteroidal anti-inflammatory drugs, on the signs of adverse effects like peptic ulcer disease and when to seek medical care. Healthcare professionals must educate patients on the importance of following postoperative instructions."
    },
    {
      "chunk_id": "doc-0de8f1773501-chunk-24",
      "publisher": "ncbi.nlm.nih.gov",
      "noi_dung": "physical examination must be focused and completed promptly. Clinicians should note abnormal vital signs and the overall discomfort of the patient. A complete abdominal examination, beginning with inspection, is essential. A patient who is completely immobilized and experiences increased pain when bumped or when the bed is moved is a sign of peritonitis. Writhing in pain is often an indication of ischemia or biliary colic. Clinicians should auscultate bowel sounds before palpating the abdomen, as this may reveal absent or hypoactive bowel sounds.\n[21]\n[22]\nTinkling, high-pitched sounds often indicate a bowel obstruction. Percussion follows, lightly at first, to identify ascites and hepatomegaly. Patients with peritonitis experience pain with gentle percussion."
    },
    {
      "chunk_id": "doc-0de8f1773501-chunk-39",
      "publisher": "ncbi.nlm.nih.gov",
      "noi_dung": "associated symptoms are nausea and vomiting.\nEvaluation\nThe history and physical examination guide the diagnostic evaluation of acute abdominal pain. Patients with unstable vital signs, evidence of peritonitis, or suspected life-threatening conditions such as ectopic pregnancy, myocardial infarction, bowel obstruction, abdominal aortic aneurysm, acute mesenteric ischemia, or perforation warrant urgent evaluation in the emergency department. Patients with potential life-threatening abdominal pathology should undergo simultaneous evaluation and resuscitation. Healthcare professionals initially assess the patient's general appearance, airway, breathing, and vital signs."
    }
  ]
}

